import React, { useMemo, useRef, useState } from 'react';
import './App.css';

type Player = 'X' | 'O';
type Cell = Player | null;
type Board = Cell[];
type NavigationKey = 'ArrowLeft' | 'ArrowRight' | 'ArrowUp' | 'ArrowDown' | 'Home' | 'End';

type GameState = {
  history: Board[];
  cursor: number;
};

const WINNING_LINES: number[][] = [
  [0, 1, 2],
  [3, 4, 5],
  [6, 7, 8],
  [0, 3, 6],
  [1, 4, 7],
  [2, 5, 8],
  [0, 4, 8],
  [2, 4, 6]
];

const NAVIGATION_KEYS: NavigationKey[] = [
  'ArrowLeft',
  'ArrowRight',
  'ArrowUp',
  'ArrowDown',
  'Home',
  'End'
];

function createEmptyBoard(): Board {
  return Array.from({ length: 9 }, () => null);
}

function calculateWinningLine(board: Board): number[] | null {
  for (const line of WINNING_LINES) {
    const [first, second, third] = line;
    const mark = board[first];
    if (mark && mark === board[second] && mark === board[third]) {
      return line;
    }
  }

  return null;
}

function cellId(index: number): string {
  return 'tic-tac-toe-cell-' + index;
}

function cellLabel(index: number, cell: Cell): string {
  const row = Math.floor(index / 3) + 1;
  const column = (index % 3) + 1;
  return 'Row ' + row + ', column ' + column + ': ' + (cell ?? 'empty');
}

export default function App() {
  const [game, setGame] = useState<GameState>(() => ({
    history: [createEmptyBoard()],
    cursor: 0
  }));
  const [focusIndex, setFocusIndex] = useState(0);
  const cellRefs = useRef<Array<HTMLButtonElement | null>>([]);

  const { history, cursor } = game;
  const board = history[cursor];
  const currentPlayer: Player = cursor % 2 === 0 ? 'X' : 'O';
  const winningLine = useMemo(() => calculateWinningLine(board), [board]);
  const winner = winningLine ? board[winningLine[0]] as Player : null;
  const isDraw = !winner && board.every((cell) => cell !== null);
  const isGameOver = winner !== null || isDraw;
  const status = winner
    ? 'Winner: ' + winner
    : isDraw
      ? 'Draw'
      : 'Next: ' + currentPlayer;
  const canUndo = cursor > 0;
  const canRedo = cursor < history.length - 1;

  const isWinningCell = (index: number): boolean => winningLine?.includes(index) ?? false;
  const isCellDisabled = (index: number): boolean => isGameOver || board[index] !== null;

  const play = (index: number) => {
    setGame((currentGame) => {
      const currentBoard = currentGame.history[currentGame.cursor];
      const currentWinningLine = calculateWinningLine(currentBoard);
      const currentIsDraw = !currentWinningLine && currentBoard.every((cell) => cell !== null);
      if (currentWinningLine || currentIsDraw || currentBoard[index] !== null) {
        return currentGame;
      }

      const nextBoard = currentBoard.slice();
      nextBoard[index] = currentGame.cursor % 2 === 0 ? 'X' : 'O';
      const retainedHistory = currentGame.history.slice(0, currentGame.cursor + 1);

      return {
        history: [...retainedHistory, nextBoard],
        cursor: currentGame.cursor + 1
      };
    });
  };

  const undo = () => {
    setGame((currentGame) => currentGame.cursor === 0
      ? currentGame
      : { ...currentGame, cursor: currentGame.cursor - 1 });
  };

  const redo = () => {
    setGame((currentGame) => currentGame.cursor >= currentGame.history.length - 1
      ? currentGame
      : { ...currentGame, cursor: currentGame.cursor + 1 });
  };

  const reset = () => {
    setGame({ history: [createEmptyBoard()], cursor: 0 });
    setFocusIndex(0);
  };

  const focusCell = (index: number) => {
    setFocusIndex(index);
    cellRefs.current[index]?.focus();
  };

  const onCellKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>, index: number) => {
    const key = event.key as NavigationKey;
    if (!NAVIGATION_KEYS.includes(key)) return;

    event.preventDefault();
    const row = Math.floor(index / 3);
    const column = index % 3;
    let nextIndex = index;

    if (key === 'ArrowLeft') nextIndex = row * 3 + (column + 2) % 3;
    else if (key === 'ArrowRight') nextIndex = row * 3 + (column + 1) % 3;
    else if (key === 'ArrowUp') nextIndex = ((row + 2) % 3) * 3 + column;
    else if (key === 'ArrowDown') nextIndex = ((row + 1) % 3) * 3 + column;
    else if (key === 'Home') nextIndex = row * 3;
    else if (key === 'End') nextIndex = row * 3 + 2;

    focusCell(nextIndex);
  };

  return (
    <main className="page">
      <section className="card">
        <h1 className="title">Tic-Tac-Toe</h1>
        <p className="subtitle">Two players take turns. First to 3 in a row wins.</p>

        <div
          id="game-status"
          className="status"
          role="status"
          aria-live="polite"
        >
          {status}
        </div>

        <div
          className="board"
          role="grid"
          aria-label="Tic tac toe board"
          aria-describedby="game-status"
        >
          {board.map((cell, index) => (
            <div key={index} className="cell-slot" role="gridcell">
              <button
                id={cellId(index)}
                ref={(element) => {
                  cellRefs.current[index] = element;
                }}
                className={'cell' + (isWinningCell(index) ? ' winning' : '')}
                type="button"
                tabIndex={focusIndex === index ? 0 : -1}
                aria-disabled={isCellDisabled(index)}
                aria-label={cellLabel(index, cell)}
                data-mark={cell ?? undefined}
                onFocus={() => setFocusIndex(index)}
                onKeyDown={(event) => onCellKeyDown(event, index)}
                onClick={() => play(index)}
              >
                {cell ?? ''}
              </button>
            </div>
          ))}
        </div>

        <div className="actions">
          <button className="ghost undo" type="button" onClick={undo} disabled={!canUndo}>
            Undo
          </button>
          <button className="ghost redo" type="button" onClick={redo} disabled={!canRedo}>
            Redo
          </button>
          <button className="ghost reset" type="button" onClick={reset}>
            Reset
          </button>
        </div>
      </section>
    </main>
  );
}

